#include "ksStateBankDisplayTask.h"
#include <iostream>
#include <stdexcept>
#include <vector>
using T=ks::StateBankDisplayTask;void check(bool b,const char* w){if(!b)throw std::runtime_error(w);}uint64_t e(unsigned kind,unsigned id,unsigned value=0){return uint64_t(kind)<<56|uint64_t(id)<<48|value;}
int main(){try{uint64_t cases=0;for(unsigned message:{0u,1u,2u,255u})for(unsigned seed=0;seed<65536;++seed){unsigned header=seed>>8,late=seed&255,program=(seed*13)&255,cursor=(seed*17)&255;T task{T::Entry::Display};std::vector<uint64_t> actual,expected;unsigned clocks=0;auto rowProgram=[&](unsigned row){return uint8_t(seed+row*17);};auto rowBank=[&](unsigned row){return (seed>>row)&3?0:unsigned(uint8_t(seed+row*31));};auto lookup=[&](unsigned row){return uint8_t(rowProgram(row)*13+row*17);};auto read=[&](T::Read r){actual.push_back(e(1,unsigned(r)));switch(r){case T::Read::MessageMode:return message;case T::Read::HeaderKind:return header;case T::Read::LateKind:return late;case T::Read::Program:return program;case T::Read::NameCursor:return cursor;case T::Read::RowProgram:return unsigned(rowProgram(task.row()));case T::Read::RowBank:return rowBank(task.row());case T::Read::RowLookup:return unsigned(lookup(task.row()));default:return 0u;}};auto write=[&](unsigned value){actual.push_back(e(2,0,value));};auto childEvent=[&](T::Child c,unsigned value){return e(3,unsigned(c),value);};while(!task.complete()&&!task.awaitingTail()){if(task.awaitingChild()){auto c=task.child();unsigned v=c==T::Child::String?unsigned(task.string())<<16|(task.string()==T::String::Label?task.labelOffset():0):c==T::Child::Number?task.number():c==T::Child::Character?task.character():c==T::Child::Formatted?task.rowBank()<<16|task.lookup()<<8|uint8_t(0xc1+task.row()*5):0;actual.push_back(childEvent(c,v));check(task.resumeChild(),"Bank display childresume");continue;}auto cost=task.nextClocks();auto n=actual.size();check(!task.advanceBefore(cost-1,read,write)&&n==actual.size(),"Bank display earlyeffect");check(task.advanceBefore(cost,read,write)==cost,"Bank display admission");clocks+=cost;}if(task.awaitingTail()){unsigned v=task.tail()==T::Tail::String?unsigned(task.string()):task.tail()==T::Tail::Character?task.character():0;actual.push_back(e(4,unsigned(task.tail()),v));check(task.retireTail(),"Bank display tailretire");}auto r=[&](T::Read r){expected.push_back(e(1,unsigned(r)));};auto c=[&](T::Child c,unsigned v=0){expected.push_back(childEvent(c,v));};auto string=[&](T::String s,unsigned offset=0){c(T::Child::String,unsigned(s)<<16|offset);};unsigned expectedClocks=0;r(T::Read::MessageMode);
if(!message){r(T::Read::HeaderKind);string(header==0?T::String::Main:header==1?T::String::Part:T::String::Other);r(T::Read::Program);c(T::Child::Number,program);r(T::Read::SelectedAddress);c(T::Child::Character,0xc0);r(T::Read::LateKind);expectedClocks=152+(header?15:0)+(header>1?9:0);if(!late){c(T::Child::PatchName);string(T::String::Name);expectedClocks+=57;}else if(late==1){expected.push_back(e(4,unsigned(T::Tail::String),unsigned(T::String::Name)));expectedClocks+=23;}else{c(T::Child::Character,0xfc);c(T::Child::Character,39);string(T::String::Name);c(T::Child::Character,39);r(T::Read::NameCursor);expected.push_back(e(4,unsigned(T::Tail::Character),uint8_t(0xc1+cursor)));expectedClocks+=127;}}
else{string(T::String::Label,(message-1)*22);c(T::Child::Character,0xfc);c(T::Child::Table);c(T::Child::BindTables);expectedClocks=175;for(unsigned row=0;row<4;++row){r(T::Read::RowProgram);r(T::Read::RowBank);if(rowBank(row)){r(T::Read::RowLookup);c(T::Child::Formatted,uint8_t(rowBank(row)-1)<<16|lookup(row)<<8|uint8_t(0xc1+row*5));expectedClocks+=131;}else{c(T::Child::Character,uint8_t(0xc1+row*5));string(T::String::Empty);expectedClocks+=105;}}c(T::Child::RestoreTables);}
check(actual==expected,"Bank display independentlateinput/format/commandorder");check(clocks==expectedClocks,"Bank display wholejob clocks");check(task.complete()&&!task.resumeChild()&&!task.retireTail(),"Bank display lifecycle");++cases;}
for(unsigned selected=0;selected<256;++selected)for(unsigned store:{0u,3u}){T task{T::Entry::Select};unsigned reads=0,writes=0,clocks=0;auto read=[&](T::Read r){check(r==T::Read::SelectedPart,"Selection observation");++reads;return selected;};auto write=[&](unsigned v){check(v==selected,"Selectedpart byte");++writes;};while(!task.awaitingTail()){auto cost=task.nextClocks(store);check(task.advanceBefore(cost,read,write,store)==cost,"Selection admission");clocks+=cost;}check(reads==1&&writes==1&&task.tail()==T::Tail::Refresh&&clocks==29+store&&task.retireTail(),"Selectedpart tail/clocks");++cases;}std::cout<<"PASS: "<<cases<<" complete bankdisplay jobs,independentheader+lateformatbytepairs/4rowfieldpatterns/typedstrings-numbers-cursor-format/order/selector/deadlines+clocks\n";return 0;}catch(const std::exception& ex){std::cerr<<ex.what()<<'\n';return 1;}}
